from fastapi import APIRouter, Depends, Query, status
from sqlalchemy.ext.asyncio import AsyncSession

from app.core.deps import get_current_user
from app.crud.review_crud import review_crud
from app.database import get_db
from app.schemas.review import ReviewCreate, ReviewOut, ReviewUpdate

# Every endpoint requires a logged-in user.
router = APIRouter(prefix="/reviews", tags=["Reviews"], dependencies=[Depends(get_current_user)])


@router.post("/", response_model=ReviewOut, status_code=status.HTTP_201_CREATED)
async def create_review(
    item_in: ReviewCreate,
    db: AsyncSession = Depends(get_db),
):
    return await review_crud.create(db, obj_in=item_in)


@router.get("/", response_model=list[ReviewOut])
async def list_reviews(
    skip: int = Query(0, ge=0),
    limit: int = Query(20, ge=1, le=100),
    db: AsyncSession = Depends(get_db),
):
    return await review_crud.get_all(db, skip=skip, limit=limit)


@router.get("/{item_id}", response_model=ReviewOut)
async def get_review(
    item_id: int,
    db: AsyncSession = Depends(get_db),
):
    return await review_crud.get(db, id=item_id)


@router.put("/{item_id}", response_model=ReviewOut)
async def replace_review(
    item_id: int,
    item_in: ReviewCreate,
    db: AsyncSession = Depends(get_db),
):
    """Full update: required fields must be sent."""
    item = await review_crud.get(db, id=item_id)
    return await review_crud.update(db, db_obj=item, obj_in=item_in.model_dump(exclude_unset=True))


@router.patch("/{item_id}", response_model=ReviewOut)
async def update_review(
    item_id: int,
    item_in: ReviewUpdate,
    db: AsyncSession = Depends(get_db),
):
    """Partial update: only the fields sent are changed."""
    item = await review_crud.get(db, id=item_id)
    return await review_crud.update(db, db_obj=item, obj_in=item_in)


@router.delete("/{item_id}")
async def delete_review(
    item_id: int,
    db: AsyncSession = Depends(get_db),
):
    await review_crud.delete(db, id=item_id)
    return {"detail": "Review deleted successfully"}
